.dm-ctm{display:flex;flex-direction:column;align-items:flex-end;gap:10px;width:100%;max-width:330px;margin-inline:auto}
.dm-ctm-pop{width:100%;padding:14px 16px 16px;border-radius:16px;box-shadow:var(--dm-shadow-pop);transform-origin:bottom right;transition:opacity .25s var(--dm-ease),transform .4s var(--dm-ease),filter .25s}
.dm-ctm.dm-shut .dm-ctm-pop{opacity:0;transform:translateY(6px) scale(.98);filter:blur(3px);pointer-events:none}
.dm-ctm-ph{display:flex;align-items:center;justify-content:space-between;margin:-4px -6px 8px 0}
.dm-ctm-ph b{font-size:14px;font-weight:500}
.dm-ctm-ib{width:28px;height:28px;color:var(--dm-fg2)}
.dm-ctm-rows{display:flex;flex-direction:column;gap:16px}
.dm-ctm-r{display:grid;grid-template-columns:1fr auto;align-items:baseline;row-gap:8px}
.dm-ctm-r .dm-l{font-size:13.5px;font-weight:500}
.dm-ctm-r .dm-p{font-size:12.5px;color:var(--dm-muted)}
.dm-ctm-tr{grid-column:1/-1;height:6px;border-radius:3px;background:var(--dm-chip);overflow:hidden}
.dm-ctm-tr i{display:block;height:100%;width:0;border-radius:inherit;background:var(--dm-accent);transition:width 1s var(--dm-ease),background .3s}
.dm-ctm-r.dm-hot .dm-ctm-tr i{background:var(--dm-warn)}
.dm-ctm-r .dm-s{grid-column:1/-1;display:flex;align-items:center;gap:8px;min-height:20px;margin-top:-2px;font-size:12.5px;color:var(--dm-muted)}
.dm-ctm-go{margin-left:auto;height:24px;padding:0 10px;border-radius:var(--dm-r-pill);font-size:12px;font-weight:500;color:var(--dm-fg);background:var(--dm-chip);transition:background var(--dm-t-fast)}
.dm-ctm-go:hover{background:var(--dm-hover)}
.dm-ctm-ft{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--dm-fg2)}
.dm-ctm-ft .dm-muted{margin-right:2px}
.dm-ctm-ring{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;transition:background var(--dm-t-fast)}
.dm-ctm-ring:hover,.dm-ctm-ring[aria-expanded="true"]{background:var(--dm-chip)}
.dm-ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.dm-ctm-ring circle{fill:none;stroke-width:2.6}
.dm-ctm-ring .dm-tr{stroke:var(--dm-rail)}
.dm-ctm-ring .dm-fl{stroke:var(--dm-accent);stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray 1s var(--dm-ease),stroke .3s}

